// Efficient smithing script
async function mineOre(pattern, count) {
    let mined = 0;
    while (mined < count) {
        if (sdk.getInventory().length >= 28) break;
        const rock = sdk.findNearbyLoc(pattern);
        if (!rock) { await sdk.waitForTicks(3); continue; }
        await sdk.sendInteractLoc(rock.x, rock.z, rock.id, 1);
        let oreCount = sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s, i) => s + i.count, 0);
        while (oreCount === mined) {
            await sdk.waitForTicks(1);
            oreCount = sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s, i) => s + i.count, 0);
        }
        mined = oreCount;
    }
    return mined;
}

