        await sdk.sendInteractLoc(rock.x, rock.z, rock.id, 1);
        let oreCount = sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s: number, i: any) => s + i.count, 0);
        while (oreCount === mined) {
            await sdk.waitForTicks(1);
            oreCount = sdk.getInventory().filter(i => pattern.test(i.name)).reduce((s: number, i: any) => s + i.count, 0);
        }
        mined = oreCount;
    }
    return mined;
}

